const PROPOSAL_STATUSES = new Set(['none','requested','rendering','pending_approval','approved','rejected','sending','partially_sent','sent','failed','blocked_after_send_failure']);
const APPOINTMENT_STATUSES = new Set(['requested','availability_checked','pending_confirmation','pending_approval','confirmed','cancelled','expired','failed']);

function text(value) { return String(value == null ? '' : value).replace(/\s+/g, ' ').trim(); }
function bool(value) { return value === true || value === 1 || /^(true|1|yes|si)$/i.test(text(value)); }
function validEmail(value) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text(value)); }
function stableHash(value) {
  let h1 = 0xdeadbeef ^ text(value).length;
  let h2 = 0x41c6ce57 ^ text(value).length;
  for (let index = 0; index < text(value).length; index += 1) {
    const code = text(value).charCodeAt(index);
    h1 = Math.imul(h1 ^ code, 2654435761);
    h2 = Math.imul(h2 ^ code, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16).padStart(14, '0');
}

function sanitizeProposalSnapshot(context, catalog) {
  const allowedContext = ['business_type','project_goal','pain_point','current_process','impact','desired_outcome','discovery_urgency','recommended_solution','selected_solution','solution_confirmed','conversation_summary'];
  const snapshot = { schema_version: '3.0', context: {}, catalog: { version: text(catalog && catalog.version), packages: {} } };
  for (const key of allowedContext) snapshot.context[key] = typeof context?.[key] === 'boolean' ? context[key] : text(context?.[key]);
  const packages = catalog?.catalog_packages || {};
  for (const key of ['PKG-ESSENTIAL','PKG-PROFESSIONAL']) {
    const row = packages[key] || {};
    snapshot.catalog.packages[key] = { name: text(row.name), price_project: Number(row.price_project || 0), price_monthly: Number(row.price_monthly || 0) };
  }
  return snapshot;
}

function buildProposalRequest(input) {
  const context = input?.context || {};
  const catalog = input?.catalog || {};
  const errors = [];
  if (!bool(context.discovery_done)) errors.push('discovery_incomplete');
  if (!bool(context.solution_confirmed)) errors.push('solution_unconfirmed');
  if (!bool(context.proposal_requested)) errors.push('proposal_not_requested');
  if (!validEmail(context.email)) errors.push('email_invalid');
  if (catalog.catalog_ready !== true) errors.push('catalog_unavailable');
  const snapshot = sanitizeProposalSnapshot(context, catalog);
  const snapshot_json = JSON.stringify(snapshot);
  const requestKey = `${text(context.conversation_id)}|${text(input.message_id)}|proposal`;
  return {
    ok: errors.length === 0,
    proposal_id: `prop_${stableHash(requestKey)}`,
    request_key: requestKey,
    conversation_id: text(context.conversation_id),
    message_id: text(input.message_id),
    status: errors.length ? 'failed' : 'requested',
    snapshot_json,
    snapshot_hash: stableHash(snapshot_json),
    recipient_email_hash: '',
    catalog_version: text(catalog.version),
    proposal_version: 1,
    requested_at: text(input.now || new Date().toISOString()),
    updated_at: text(input.now || new Date().toISOString()),
    environment: text(input.environment || 'staging'),
    source_version: text(input.source_version || '3.0'),
    last_error_code: errors.join(','),
  };
}

function parseApprovalCommand(input) {
  const body = text(input?.content || input?.message);
  const privateNote = bool(input?.private_note || input?.private);
  const human = bool(input?.human_sender) && !bool(input?.sender_is_bot);
  const hmac = bool(input?.hmac_valid);
  const match = body.match(/^\/luna\s+(aprobar|rechazar)\s+(propuesta|cita)\s+([a-z0-9_-]+)(?:\s+(.+))?$/i);
  if (!hmac) return { ok: false, reason_code: 'INVALID_SIGNATURE' };
  if (!privateNote) return { ok: false, reason_code: 'COMMAND_NOT_PRIVATE' };
  if (!human) return { ok: false, reason_code: 'COMMAND_SENDER_NOT_HUMAN' };
  if (!match) return { ok: false, reason_code: 'COMMAND_INVALID' };
  const action = match[1].toLowerCase();
  const request_type = match[2].toLowerCase() === 'propuesta' ? 'proposal' : 'appointment';
  if (action === 'rechazar' && !text(match[4])) return { ok: false, reason_code: 'REJECTION_REASON_REQUIRED' };
  return { ok: true, action: action === 'aprobar' ? 'approve' : 'reject', request_type, request_id: match[3], reason: text(match[4]), reason_code: 'APPROVAL_COMMAND_VALID' };
}

function validateMedia(input) {
  const mime = text(input?.mime_type).toLowerCase();
  const bytes = Number(input?.size_bytes || 0);
  const duration = Number(input?.duration_seconds || 0);
  const audio = ['audio/ogg','audio/mpeg','audio/mp4','audio/webm'].includes(mime);
  const image = ['image/jpeg','image/png','image/webp'].includes(mime);
  if (!audio && !image) return { ok: false, kind: 'unsupported', reason_code: 'MEDIA_MIME_UNSUPPORTED' };
  if (audio && bytes > 10 * 1024 * 1024) return { ok: false, kind: 'audio', reason_code: 'MEDIA_TOO_LARGE' };
  if (audio && duration > 300) return { ok: false, kind: 'audio', reason_code: 'MEDIA_TOO_LONG' };
  if (image && bytes > 8 * 1024 * 1024) return { ok: false, kind: 'image', reason_code: 'MEDIA_TOO_LARGE' };
  return { ok: true, kind: audio ? 'audio' : 'image', reason_code: 'MEDIA_ACCEPTED' };
}

function validateAppointment(input) {
  const context = input?.context || {};
  const status = text(input?.status || 'requested');
  const errors = [];
  if (!APPOINTMENT_STATUSES.has(status)) errors.push('appointment_status_invalid');
  if (!validEmail(context.email)) errors.push('email_invalid');
  if (!bool(input?.consent_explicit)) errors.push('consent_required');
  if (text(input?.timezone || 'America/Bogota') !== 'America/Bogota') errors.push('timezone_invalid');
  return { ok: errors.length === 0, status: errors.length ? 'failed' : status, duration_minutes: 30, buffer_minutes: 15, timezone: 'America/Bogota', reason_code: errors.join(',') || 'APPOINTMENT_VALID' };
}

function transitionProposal(current, event) {
  const status = PROPOSAL_STATUSES.has(text(current)) ? text(current) : 'none';
  const transitions = {
    none: { request: 'requested' }, requested: { render: 'rendering', fail: 'failed' }, rendering: { rendered: 'pending_approval', fail: 'failed' },
    pending_approval: { approve: 'approved', reject: 'rejected' }, approved: { send: 'sending' }, sending: { partial: 'partially_sent', delivered: 'sent', fail_after_send: 'blocked_after_send_failure', fail: 'failed' },
    partially_sent: { delivered: 'sent', fail_after_send: 'blocked_after_send_failure' }, rejected: {}, sent: {}, failed: {}, blocked_after_send_failure: {},
  };
  const next = transitions[status]?.[text(event)];
  return { ok: Boolean(next), previous_status: status, status: next || status, proposal_sent_this_turn: next === 'sent' && status !== 'sent', reason_code: next ? 'PROPOSAL_TRANSITION_OK' : 'PROPOSAL_TRANSITION_BLOCKED' };
}


